SELECT AVG(`Percent (%) Eligible Free (Ages 5-17)`) AS free_rate
FROM frpm
WHERE LOWER(`School Name`) LIKE '%kacey gibson%';

SELECT AVG(loan.amount) AS avg_loan_amount
FROM loan
JOIN client ON loan.account_id = (
    SELECT account_id FROM disp WHERE disp.client_id = client.client_id
)
WHERE LOWER(client.gender) = LOWER('M');

SELECT COUNT(*) AS total_dispositions
FROM disp
WHERE account_id BETWEEN 1 AND 10;

SELECT strftime('%Y', client.birth_date) AS birth_year
FROM client
WHERE client.client_id = 130;

SELECT CAST(SUM(CASE WHEN LOWER(gender) = 'f' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS female_proportion
FROM client
WHERE district_id IN (SELECT district_id FROM district WHERE A2 LIKE '%prague%');

SELECT 
  (SELECT COUNT(DISTINCT a.atom_id) FROM atom a JOIN connected c ON a.atom_id = c.atom_id JOIN bond b ON c.bond_id = b.bond_id WHERE LOWER(a.element) = 'i' AND LOWER(b.bond_type) = '-') AS iodine_count,
  (SELECT COUNT(DISTINCT a.atom_id) FROM atom a JOIN connected c ON a.atom_id = c.atom_id JOIN bond b ON c.bond_id = b.bond_id WHERE LOWER(a.element) = 's' AND LOWER(b.bond_type) = '-') AS sulfur_count;

SELECT a.element
FROM atom a
WHERE a.atom_id NOT IN (SELECT DISTINCT atom_id FROM connected);

SELECT c.atom_id2 AS bonded_atom_id, a.element AS bonded_element
FROM connected c
JOIN atom a ON c.atom_id2 = a.atom_id
WHERE LOWER(c.atom_id) IN (
    SELECT atom_id FROM atom WHERE LOWER(element) = 'pb'
);

